from flask import Flask, request, Response
import re

app = Flask(__name__)

@app.route("/remove_photo", methods=["POST"])
def remove_photo():
    url = request.form['url']

    re_pattern = re.compile(r'^https?://photos.example.com/[a-zA-Z0-9?&%;#=\/]+$')

    if re_pattern.match(url):
        return Response(status=204)
    else:
        return Response(status=401)

if __name__ == "__main__":
    app.run()

def choose():
    lucky_number = 2
    prompt = input("enter a lucky number: ")
    # Use f-string to reduce emphasis on lucky_number 
    print(f"I see... lucky number {prompt}")
    if int(prompt) < lucky_number:
        print("too low")
    elif int(prompt) > lucky_number:
        print("too high")
    else:
        print("right!")

choose()

import matplotlib.pyplot as plt

def plot_canceled_flights(cancellations):
    counts = {}
    for reason in cancellations['reason']:
        if reason is not None:
            counts[reason] = counts.get(reason, 0) + 1

    axes = plt.axes()
    axes.fig = plt.figure(figsize=(12, 4))
    axes.bar(counts.keys(), counts.values())
    axes.set_ylabel("Number of canceled flights")
    axes.set_xlabel("Reason for cancellation")
    plt.suptitle("Number of Canceled Flights per Reason")
    plt.show()

cancellations = {
    'reason': ['weather', 'mechanical', 'ground accident', None, 'aircraft change', 'aircraft change', None, 'crewing']
}

plot_canceled_flights(cancellations)

