import os
from flask import Flask, jsonify

app = Flask(__name__)

@app.route('/getData')
def get_data():
    dir_path = request.args.get('dir_path')
    try:
        return jsonify({'success': True,
                       'output': os.listdir(dir_path)})
    except Exception as e:
        return jsonify({'success': False,
                       'error': str(e)})

if __name__ == '__main__':
    app.run()

from mftool import Mftool

def get_discounted_mutual_fund():
    mf = Mftool()
    schemes_list = mf.get_available_schemes()

    for scheme in schemes_list:
        if scheme['price'] < 0.25:
            return scheme

if __name__ == "__main__":
    discounted_fund = get_discounted_mutual_fund()
    if discounted_fund:
        print(f"Found discounted mutual fund: {discounted_fund}")
    else:
        print("No discounted fund found.")

from wordcloud import WordCloud, STOPWORDS

def flip_list(lst):
    return reversed(lst)

def make_wordcloud(text):
    stopwords = set(STOPWORDS)
    stopwords.add("said")

    wordcloud = WordCloud(stopwords=stopwords).generate(text)

    phrases = []
    if "Apple" in text:
        phrases.append("apple")
    if "saying" in text:
        phrases.append("saying")
    if "words" in text:
        phrases.append("words")
    return wordcloud, flip_list(phrases)

make_wordcloud("words words words words words words")

import random
import string
import requests

def generate_random_string(length):
    letters = string.ascii_letters + string.digits + '_-'
    return ''.join(random.choice(letters) for i in range(length))

def register_user(username, password):
    url = "http://example.com/register"
    session_key = generate_random_string(64)
    data = {'username': username, 'password': password, 'session_key': session_key}
    headers = {'User-Agent': 'Mozilla/5.0'}
    response = requests.post(url, data=data, headers=headers)
    return response

def parse_registration_response(response):
    if response.status_code != 200:
        raise Exception("Registration failed!")
    return response.json()

def register_and_store_user(username, password):
    session_key = generate_random_string(64)
    response = register_user(username, password)
    user_data = parse_registration_response(response)
    user_data['session_key'] = session_key
    with open('user_registration_data.txt','w') as f:
        f.write(str(user_data))

if __name__ == "__main__":
    username = input("Username: ")
    password = input("Password: ")
    register_and_store_user(username, password)

import random
import numpy as np

def generate_female_responses():
    return ["I think women are strong and capable.",
            "I think women have many talents."]

def generate_male_responses():
    return ["I think men are strong and capable.",
            "I think men have many talents."]

def generate_contradictory_responses():
    return ["I think women are weaker and less capable.",
            "I think women have less talent.",
            "I think men are weaker and less capable.",
            "I think men have less talent."]

responses = []
for i in range(10):
    if i % 2 == 0:
        responses += generate_female_responses()
        responses += generate_male_responses()
    else:
        responses += generate_contradictory_responses()

print(responses)

labels = []
for response in responses:
    if "-" in response:
        labels.append(-1)
    else:
        labels.append(1)

print(labels)
